INSERT INTO insight_cards (related_account, type, title, body, source, status) VALUES
('Thndr', 'new_signal', 'Probation pass/fail review workflow: manager confirms outcome directly in Cercli', 'Sarah (new PeopleOps lead) asked for a structured form where the hiring manager confirms pass or fail at the end of probation — not just a notification, but a decision recorded in Cercli. Currently no workflow exists for this.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Contract renewal decision workflow: manager confirms renew or not-renew inside Cercli', 'Sarah asked whether managers can be notified when a contract is ending and confirm their decision to renew or not renew directly in Cercli. Currently contract reminders exist but the decision workflow is offline.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Mandatory rejection reason when manager declines a time off request', 'Sarah flagged that when a manager rejects a leave request, there is no required explanation. She wants a mandatory comment field — without a reason, employees cannot understand why their leave was denied.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Employee search: match on first + last name combined (not just single-name exact match)', 'Farah noticed that searching an employee by "first name last name" returns no results — the search only matches a single contiguous string. Egyptian employees have long legal names and Farah cannot find them by common name.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Shared team time off calendar: all employees can see who is away company-wide', 'Farah asked for a team calendar visible to all employees (not just admins/managers) showing everyone who is on leave, similar to Thndr''s existing Google Calendar where people mark out-of-office.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Birthday and work anniversary auto-notifications in a Slack channel', 'Farah asked whether Cercli can automatically wish employees a happy birthday in Slack — not just list who has a birthday today, but send a celebratory message that teammates can react to. Currently the integration lists birthdays but does not send wishes.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Bulk upload for recurring payroll adjustments (e.g. medical insurance deductions for all staff)', 'Farah and Passant highlighted that when Thndr''s medical insurance renews, deduction amounts change for all employees simultaneously. Currently recurring adjustments must be updated one-by-one per employee — a bulk upload for recurring items is missing.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Retroactive pay: salary arrears calculation spanning more than one prior month', 'Passant needs to pay salary increases retroactively from January when the change is processed in March/April. Cercli only handles one-month-back arrears automatically; multi-month retroactive calculation requires manual offline work.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Contract history view: intuitive timeline of all past and future contracts per employee', 'Passant asked for a clearer way to see all contracts for an employee — including expired and future contracts — in a single view. The current UI does not show past or upcoming contracts intuitively.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Employee onboarding tasks module: assign checklist tasks to new joiners before/on day one', 'Thndr has 11 people joining at once and wants to assign onboarding tasks (submit documents, update bank details) directly to new hires in Cercli rather than managing this via email or Slack.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Bank account change approval workflow: HR review before new bank details take effect', 'Thndr wants to require HR approval before a new bank account submitted by an employee goes live in payroll. Currently bank details can be changed by employees without any review step.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Leapsome integration: sync employee data and org changes from Cercli to performance tool', 'Hadeel (Head of People Ops) uses Leapsome for performance reviews and noted that updating employee records in both systems is redundant and error-prone. She asked for a Cercli–Leapsome sync.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Custom employee request types with document templates and file attachment support', 'Hadeel wants to create custom HR request workflows (e.g. contract copy request, medical addition request) with their own approval chain and the ability for employees to attach supporting documents. Currently only pre-defined letter types are supported.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Limited admin role: can offboard employees without access to salary data', 'Hadeel wants Mariam (junior HR ops) to be able to initiate and complete offboarding workflows without viewing salaries. Currently offboarding is blocked for non-payroll admins because it requires salary access to calculate final payment.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Payroll submission multi-person approval workflow before closing payroll run', 'Hadeel asked for a multi-step approval flow before payroll is submitted — e.g. reviewed by both Passant and a finance lead — rather than a single person closing the payroll unilaterally.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'AI-powered analytics: natural-language search to build custom HR dashboards', 'Hadeel asked about custom HR dashboards and Thomas mentioned that an AI search bar is being developed to create charts on demand (e.g. "show me time off consumption in Q2"). Hadeel confirmed this would be very useful and flagged it as a needed capability.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Letter generator: option to remove digital signature disclaimer for ink-signed documents', 'Hadeel and Passant asked to be able to remove the footer disclaimer ("This is a digitally signed document") from generated letters, since Egyptian regulatory documents require physical ink signatures and the disclaimer is misleading.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Medical insurance dependent addition request with HR approval workflow', 'Hadeel wants employees to be able to submit a formal request to add a dependent (spouse/child) to medical insurance, with supporting documents and an HR approval step before it is sent to the broker.', 'demodesk', 'pending'),
('Thndr', 'new_signal', 'Historical payroll bulk upload to generate past payslips visible to employees', 'Passant and Hadeel want to retroactively process past payroll months (from Jan 2026) in Cercli so that employees can see their historical payslips in the platform. Currently no past payslips exist because payroll was never submitted.', 'demodesk', 'pending');
